import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import type { ThemeWebFont } from '@ox-content/vite-plugin';
import ja from './ja.json' with { type: 'json' };

const file = path.join(import.meta.dirname, 'shippori-mincho-b1-bold-ja.woff2');

// ox-content names the emitted file after the family, weight, style and subset, so a content
// hash as the subset gives the file a name that changes with its bytes and caches for good.
const hash = createHash('sha256').update(readFileSync(file)).digest('hex').slice(0, 10);

// Regenerated by `just font` from the Japanese in docs/.
export const japaneseFont = {
	family: 'Shippori Mincho B1',
	path: file,
	selfHost: true,
	weights: [700],
	subsets: [hash],
	display: 'swap',
	unicodeRange: ja.unicodeRange,
	preload: true,
} satisfies ThemeWebFont;
